<script src="<https://js.pusher.com/8.2.0/pusher.min.js>"></script>
<script>
    const token = localStorage.getItem("auth_token");
    const chatIdentity = "{{ $chatIdentity }}"

    console.log("incoming....")
    document.addEventListener("DOMContentLoaded", () => {
        console.log("starting okay...")
        Echo.private(`chat.${chatIdentity}`)
            .subscribed(() => {
                console.log("✅ Subscribed to chat channel:", `chat.${chatIdentity}`);
            })
            .listenToAll((event, name) => {
                console.log("event", event)
            })
            .listen("message.sent", (e) => {
                console.log("📩 Dot Event:", e);
            })
            .error((error) => {
                console.error("❌ Subscription error:", error);
            });


        // Listen for incoming messages", e));
        // window.Echo.private(`chat.${chatIdentity}`)
        //     .listenToAll((event, data) => {
        //         console.log("📡 Incoming Event:", event, data);
        //     });


        // Listen for incoming messages
        // window.Echo.private(`chat.${chatIdentity}`)
        //     .listen('.message.delivered', (e) => {
        //         console.log("✅ New Message Delivered: ", e.message);
        //         markedAsSeen(chatIdentity, e.message.message_id)
        //
        //     });

        // Listen for incoming messages
        // Echo.private(`chat.${chatIdentity}`)
        //     .subscribe()
        //     .listen('.message.seen', (e) => {
        //         console.log("✅ Message Seen: ", e.message);
        //     });

        $.ajax({
            url: "/api/v1/chat/private/messages",
            method: "GET",
            data: {
                chat_identity: "{{ $chatIdentity }}",
                page: 1
            },
            beforeSend: function (xhr) {
                let token = localStorage.getItem("auth_token");
                console.log("Sending token:", token);
                if (token) {
                    xhr.setRequestHeader("Authorization", "Bearer " + token);
                }
            },
            success: function (res) {
                console.log("Success:", res);
            },
            error: function (err) {
                console.log("Error:", err);
            }
        });

        function markedAsSeen(chatIdentity, message_id) {
            console.log("marked as seen called")
            $.ajax({
                url: `/api/v1/chat/marked-as-seen`, // Your Laravel API endpoint
                method: "POST",
                data: {
                    chat_identity: "{{ $chatIdentity }}",
                    message_id: message_id
                },
                headers: {
                    "Authorization": `Bearer ${token}` // if using auth token
                },
                success: function (res) {
                    $('#message').val(''); // Clear input
                },
                error: function (err) {
                    alert("Failed to send message");
                }
            });
        }


        function messageDelivered(chatIdentity, message_id) {

            $.ajax({
                url: `/api/v1/chat/delivered`, // Your Laravel API endpoint
                method: "POST",
                data: {
                    chat_identity: "{{ $chatIdentity }}",
                    message_id: message_id
                },
                headers: {
                    "Authorization": `Bearer ${token}` // if using auth token
                },
                success: function (res) {
                    $('#message').val(''); // Clear input
                },
                error: function (err) {
                    alert("Failed to send message");
                }
            });
        }


        function sendMessage() {
            let messageInput = document.getElementById('messageInput');
            let messageText = messageInput.value.trim();
            if (messageText === '') return;

            let chatMessages = document.getElementById('chatMessages');

            let message = document.createElement('div');
            message.classList.add('message', 'sent');
            message.innerHTML = `
                    ${messageText}
                    <div class="timestamp">${new Date().toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'})}</div>
                `;

            chatMessages.appendChild(message);
            chatMessages.scrollTop = chatMessages.scrollHeight;

            messageInput.value = '';

            $.ajax({
                url: "/api/v1/chat/message/create", // Your Laravel API endpoint
                method: "POST",
                data: {
                    chat_id: "{{ $chatIdentity }}",
                    message: messageText.toString()
                },
                headers: {
                    "Authorization": `Bearer ${token}` // if using auth token
                },
                success: function (res) {
                    $('#message').val(''); // Clear input
                },
                error: function (err) {
                    alert("Failed to send message");
                }
            });
        }
    });


</script>
</body>
</html>

